"""rival_bot: 8-max NLHE sit-and-go bot. Pure stdlib, sub-millisecond decisions.
Preflop: 169x169 equity matrix + opponent-range estimates + ICM push/fold.
Postflop: time-boxed range-weighted Monte Carlo with aggression narrowing.
Opponent model: per-seat counters rebuilt each table from a replay of the action history."""
import random, time, gc
try:
    from kit import Agent
except Exception:  # pragma: no cover
    class Agent(object):
        def new_table(self, rules, seat, n_players): pass
        def act(self, obs): raise NotImplementedError
        def hand_end(self, result): pass

_pc = time.perf_counter_ns

# ---------------------------------------------------------------- evaluator
M31 = (1 << 31) - 1
CK = [5 ** (c >> 2) + (1 << (31 + 3 * (c & 3))) for c in range(52)]
RB = [1 << (c >> 2) for c in range(52)]


def _straight_top(mask):
    for top in range(12, 3, -1):
        m = 0x1F << (top - 4)
        if mask & m == m:
            return top
    if mask & 0x100F == 0x100F:
        return 3
    return -1


STR = [_straight_top(m) for m in range(8192)]


def _topk(mask, k):
    out = []
    r = 12
    while r >= 0 and len(out) < k:
        if mask >> r & 1:
            out.append(r)
        r -= 1
    return out


def _pack(cat, ks):
    v = cat
    for i in range(5):
        v = v * 16 + (ks[i] if i < len(ks) else 0)
    return v


FL = [0] * 8192
for _m in range(8192):
    if bin(_m).count('1') >= 5:
        _t = STR[_m]
        FL[_m] = _pack(8, [_t]) if _t >= 0 else _pack(5, _topk(_m, 5))


def _nf_value(counts):
    mask = 0
    quads = []; trips = []; pairs = []
    for r in range(12, -1, -1):
        c = counts[r]
        if c:
            mask |= 1 << r
            if c == 4: quads.append(r)
            elif c == 3: trips.append(r)
            elif c == 2: pairs.append(r)
    if quads:
        q = quads[0]
        return _pack(7, [q] + _topk(mask & ~(1 << q), 1))
    if trips and (len(trips) >= 2 or pairs):
        p = max(trips[1] if len(trips) > 1 else -1, pairs[0] if pairs else -1)
        return _pack(6, [trips[0], p])
    st = STR[mask]
    if st >= 0:
        return _pack(4, [st])
    if trips:
        t = trips[0]
        return _pack(3, [t] + _topk(mask & ~(1 << t), 2))
    if len(pairs) >= 2:
        a, b = pairs[0], pairs[1]
        return _pack(2, [a, b] + _topk(mask & ~(1 << a) & ~(1 << b), 1))
    if pairs:
        a = pairs[0]
        return _pack(1, [a] + _topk(mask & ~(1 << a), 3))
    return _pack(0, _topk(mask, 5))


NF = {}


def _gen(r, left, counts, key):
    if r < 0:
        if left == 0:
            NF[key] = _nf_value(counts)
        return
    p = 5 ** r
    for c in range(min(4, left) + 1):
        counts[r] = c
        _gen(r - 1, left - c, counts, key + c * p)
    counts[r] = 0


for _n in (5, 6, 7):
    _gen(12, _n, [0] * 13, 0)
FS = [-1] * 4096
for _p in range(4096):
    for _s in range(4):
        if (_p >> (3 * _s)) & 7 >= 5:
            FS[_p] = _s


def ev(cards):
    k = 0
    for c in cards:
        k += CK[c]
    fs = FS[k >> 31]
    if fs < 0:
        return NF[k & M31]
    m = 0
    for c in cards:
        if c & 3 == fs:
            m |= RB[c]
    return FL[m]

# ---------------------------------------------------------------- preflop tables
_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
_BI = {ch: i for i, ch in enumerate(_B64)}
_EQS = ''
_EQK = ''


def _dec(s):
    bi = _BI
    return [(bi[s[i]] * 64 + bi[s[i + 1]]) / 4095.0 for i in range(0, len(s), 2)]


EQ = _dec(_EQS)          # EQ[i*169+j]: equity of class i vs class j
_k = _dec(_EQK)
EQK = [[0.0] + _k[i * 7:(i + 1) * 7] for i in range(169)]   # EQK[i][k]: vs k random hands
del _k


def cls_of(c1, c2):
    r1, r2 = c1 >> 2, c2 >> 2
    if r1 < r2: r1, r2 = r2, r1
    if r1 == r2: return r1 * 14
    if (c1 & 3) == (c2 & 3): return r1 * 13 + r2
    return r2 * 13 + r1


CLS = [0] * 2704
for _a in range(52):
    for _b in range(52):
        if _a != _b:
            CLS[_a * 52 + _b] = cls_of(_a, _b)
NCOMB = [0] * 169
for _a in range(52):
    for _b in range(_a + 1, 52):
        NCOMB[CLS[_a * 52 + _b]] += 1
HUR = [sum(EQ[i * 169 + j] * NCOMB[j] for j in range(169)) / 1326.0 for i in range(169)]
# ranking used to model opponents' ranges: mostly HU strength, some multiway playability
ORDER = sorted(range(169), key=lambda i: -(HUR[i] * 0.7 + EQK[i][3] * 1.2))
PCT = [0.0] * 169       # fraction of combos ranked at or above this class
PCT_LO = [0.0] * 169    # fraction strictly above
_c = 0
for _i in ORDER:
    PCT_LO[_i] = _c / 1326.0
    _c += NCOMB[_i]
    PCT[_i] = _c / 1326.0
# all combos in ranking order (for range sampling)
_byc = [[] for _ in range(169)]
for _a in range(52):
    for _b in range(_a + 1, 52):
        _byc[CLS[_a * 52 + _b]].append((_a, _b))
ALLA = []; ALLB = []
for _i in ORDER:
    for (_a, _b) in _byc[_i]:
        ALLA.append(_a); ALLB.append(_b)
del _byc
# equity of class vs top-x range (x grid), from the matrix
XS = [0.02, 0.035, 0.05, 0.07, 0.09, 0.12, 0.15, 0.19, 0.24, 0.30, 0.37, 0.45, 0.55, 0.70, 0.85, 1.0]
EQTOP = []
for _i in range(169):
    row = []
    base = _i * 169
    acc = 0.0; w = 0.0; k = 0; cum = 0
    for _x in XS:
        lim = _x * 1326.0
        while k < 169 and cum + NCOMB[ORDER[k]] <= lim + 1e-9:
            j = ORDER[k]; acc += EQ[base + j] * NCOMB[j]; w += NCOMB[j]; cum += NCOMB[j]; k += 1
        part = 0.0; pacc = 0.0
        if k < 169 and lim > cum:
            j = ORDER[k]; part = lim - cum; pacc = EQ[base + j] * part
        row.append((acc + pacc) / (w + part) if (w + part) > 0 else 0.5)
    EQTOP.append(row)


def eq_top(c, x):
    if x <= XS[0]:
        return EQTOP[c][0]
    if x >= 1.0:
        return EQTOP[c][-1]
    i = 1
    while XS[i] < x:
        i += 1
    x0 = XS[i - 1]; x1 = XS[i]; r = EQTOP[c]
    return r[i - 1] + (r[i] - r[i - 1]) * (x - x0) / (x1 - x0)


POINTS = [10, 7, 5, 4, 3, 2, 1, 0]


def icm_me(me, others, pts):
    """Harville equity of stack `me` against `others` over pts (places 1..). Exact for <=5 others."""
    others = [x for x in others if x > 0]
    if me <= 0:
        return 0.0 if len(pts) <= len(others) + 1 else pts[len(others) + 1] if len(others) + 1 < len(pts) else 0.0
    k = len(others)
    if k == 0:
        return pts[0]
    if k <= 4:
        tot = me + sum(others)
        # dp over subsets of others placed above me
        res = 0.0
        prob = {0: 1.0}
        sums = {0: 0}
        for size in range(k + 1):
            nxt = {}
            for msk, p in prob.items():
                rem = tot - sums[msk]
                res += p * me / rem * (pts[size] if size < len(pts) else 0.0)
                if size < k:
                    for j in range(k):
                        if not msk >> j & 1:
                            nm = msk | (1 << j)
                            q = p * others[j] / rem
                            if nm in nxt:
                                nxt[nm] += q
                            else:
                                nxt[nm] = q; sums[nm] = sums[msk] + others[j]
            prob = nxt
        return res
    m = sum(others) / float(k)
    # equal-others approximation, exact recursion on count
    res = 0.0; reach = 1.0; kk = k
    for place in range(k + 1):
        tot = me + kk * m
        pm = me / tot
        res += reach * pm * (pts[place] if place < len(pts) else 0.0)
        reach *= (1.0 - pm)
        kk -= 1
        if kk < 0:
            break
    return res

# ---------------------------------------------------------------- opponent model


class Opp(object):
    __slots__ = ('hands', 'vpip', 'pfr', 'un_opp', 'un_raise', 'un_limp', 'fo_opp', 'fo_fold', 'fo_call',
                 'fo_3b', 'f3_opp', 'f3_fold', 'f3_cont', 'shoves', 'nb_opp', 'nb_bet', 'fb_opp', 'fb_fold',
                 'fb_raise', 'fb_call', 'big_bets', 'pfa_ops', 'cbets')

    def __init__(self):
        for k in self.__slots__:
            setattr(self, k, 0)

    def rate(self, num, den, prior, w):
        return (num + prior * w) / (den + w)

    def vpip_rate(self):
        return self.rate(self.vpip, self.hands, 0.25, 6.0)

    def open_rate(self):
        return self.rate(self.un_raise, self.un_opp, 0.16, 5.0)

    def threebet_rate(self):
        return self.rate(self.fo_3b, self.fo_opp, 0.06, 6.0)

    def shove_rate(self):
        return self.rate(self.shoves, self.hands, 0.03, 8.0)

    def call_vs_raise(self):
        return self.rate(self.fo_call + self.fo_3b, self.fo_opp, 0.22, 5.0)

    def fold_to_raise(self):
        return self.rate(self.fo_fold, self.fo_opp, 0.75, 5.0)

    def bet_rate(self):
        return self.rate(self.nb_bet, self.nb_opp, 0.40, 6.0)

    def fold_to_bet(self):
        return self.rate(self.fb_fold, self.fb_opp, 0.45, 6.0)

    def raise_vs_bet(self):
        return self.rate(self.fb_raise, self.fb_opp, 0.10, 6.0)

    def wild(self):
        """0 = normal, ->1 = random/maniac-like."""
        v = self.vpip_rate(); p = self.rate(self.pfr, self.hands, 0.15, 6.0)
        return max(0.0, min(1.0, (v - 0.45) / 0.35)) * 0.5 + max(0.0, min(1.0, (p - 0.30) / 0.30)) * 0.5


class Replay(object):
    """Re-simulates the hand's betting from obs.history to attribute actions to streets."""
    __slots__ = ('n', 'stk', 'bet', 'inh', 'street', 'mx', 'acted', 'idx', 'ok', 'pf_raises', 'pf_raiser',
                 'st_raises', 'aggr', 'aggr_cnt', 'first_act', 'sb', 'bb', 'sbs', 'bbs', 'skip', 'last_aggr',
                 'limpers', 'pf_callers', 'start', 'cur_actions', 'pf_act')

    def __init__(self, n, start, button, sb, bb):
        self.n = n; self.start = start[:]
        self.stk = start[:]; self.bet = [0] * n; self.inh = [s > 0 for s in start]
        self.street = 0; self.acted = set(); self.idx = 0; self.ok = True
        self.pf_raises = 0; self.pf_raiser = -1; self.st_raises = 0; self.aggr = -1
        self.aggr_cnt = [[0] * 4 for _ in range(n)]
        self.first_act = [True] * n; self.sb = sb; self.bb = bb; self.last_aggr = -1
        self.limpers = 0; self.pf_callers = 0; self.cur_actions = []; self.pf_act = [''] * n
        alive = [s for s in range(n) if start[s] > 0]
        order = []
        s = (button + 1) % n
        for _ in range(n):
            if start[s] > 0: order.append(s)
            s = (s + 1) % n
        if len(alive) == 2:
            self.sbs = button if start[button] > 0 else order[0]
            self.bbs = [x for x in alive if x != self.sbs][0]
        elif len(order) >= 2:
            self.sbs = order[0]; self.bbs = order[1]
        else:
            self.sbs = self.bbs = -1
        for s, a in ((self.sbs, sb), (self.bbs, bb)):
            if s >= 0:
                x = min(a, self.stk[s]); self.stk[s] -= x; self.bet[s] += x
        self.mx = bb
        self.skip = 0

    def feed(self, hist, opps, me):
        n = self.n
        while self.idx < len(hist):
            i = self.idx; self.idx += 1
            try:
                s, a = hist[i]; kind = a[0]; amt = a[1] if len(a) > 1 else 0
            except Exception:
                continue
            if kind not in ('fold', 'check', 'call', 'raise'):
                k2 = str(kind).lower()
                if k2 in ('bet', 'allin', 'all-in', 'all_in', 'raise_to', 'shove'):
                    kind = 'raise'
                    if not isinstance(amt, int) or amt <= 0:
                        amt = self.bet[s] + self.stk[s] if 0 <= s < n else 0
                else:
                    continue
            if self.street == 0 and not self.acted and self.skip < 2 and s in (self.sbs, self.bbs) and \
                    isinstance(amt, (int, float)) and (
                        (kind == 'raise' and amt <= self.bb) or
                        (kind == 'call' and i == self.skip and ((s == self.sbs and amt == self.sb and self.skip == 0) or
                                                                (s == self.bbs and amt == self.bb and self.skip == 1)))):
                self.skip += 1
                continue
            if not (0 <= s < n):
                continue
            self.apply(s, kind, amt, opps[s] if s != me else None)

    def apply(self, s, kind, amt, o):
        st = self.street
        to_call = max(0, self.mx - self.bet[s])
        facing = to_call > 0
        if st == 0 and o is not None:
            if self.first_act[s]:
                o.hands += 1
                if self.pf_raises == 0:
                    o.un_opp += 1
                    if kind == 'raise': o.un_raise += 1
                    elif kind == 'call': o.un_limp += 1
                elif self.pf_raises == 1:
                    o.fo_opp += 1
                    if kind == 'fold': o.fo_fold += 1
                    elif kind == 'call': o.fo_call += 1
                    elif kind == 'raise': o.fo_3b += 1
                if kind == 'raise' or (kind == 'call' and s != self.bbs) or (kind == 'call' and facing):
                    o.vpip += 1
                if kind == 'raise': o.pfr += 1
            elif self.pf_raises >= 2 or (self.pf_raises >= 1 and self.pf_raiser == s):
                o.f3_opp += 1
                if kind == 'fold': o.f3_fold += 1
                else: o.f3_cont += 1
            if kind == 'raise' and isinstance(amt, int) and amt >= self.bet[s] + self.stk[s] - 1 \
                    and self.stk[s] + self.bet[s] > 0:
                o.shoves += 1
        elif o is not None:
            if facing:
                o.fb_opp += 1
                if kind == 'fold': o.fb_fold += 1
                elif kind == 'raise': o.fb_raise += 1
                else: o.fb_call += 1
            else:
                o.nb_opp += 1
                if kind == 'raise':
                    o.nb_bet += 1
                    if st == 1 and self.pf_raiser == s and self.st_raises == 0:
                        o.cbets += 1
                if st == 1 and self.pf_raiser == s and self.st_raises == 0:
                    o.pfa_ops += 1
        if st == 0:
            self.first_act[s] = False
            self.pf_act[s] = kind
        if kind == 'fold':
            self.inh[s] = False
        elif kind == 'call':
            x = min(to_call, self.stk[s]); self.stk[s] -= x; self.bet[s] += x
            if st == 0:
                if self.pf_raises == 0: self.limpers += 1
                else: self.pf_callers += 1
        elif kind == 'raise':
            if not isinstance(amt, int): amt = int(amt)
            x = max(0, min(amt - self.bet[s], self.stk[s]))
            self.stk[s] -= x; self.bet[s] += x
            if self.bet[s] > self.mx:
                self.mx = self.bet[s]
            self.acted = set()
            self.st_raises += 1; self.aggr = s; self.last_aggr = s
            self.aggr_cnt[s][st] += 1
            if st == 0:
                self.pf_raises += 1; self.pf_raiser = s; self.pf_callers = 0
        self.acted.add(s)
        self.cur_actions.append((s, (kind, amt)))
        # round complete?
        live = [i for i in range(self.n) if self.inh[i]]
        if len(live) <= 1:
            return
        need = [i for i in live if self.stk[i] > 0 and (i not in self.acted or self.bet[i] < self.mx)]
        if not need:
            self.street += 1
            self.bet = [0] * self.n; self.mx = 0; self.acted = set(); self.st_raises = 0; self.aggr = -1
            self.cur_actions = []

# ---------------------------------------------------------------- the bot


class Bot(Agent):
    VERSION = 'v1'

    def __init__(self, params=None):
        self.rng = random.Random()
        self.P = {
            'open_mult': 1.0, 'push_bb': 13.0, 'cbet': 0.55, 'vbet_hu': 0.60, 'vbet_mw': 0.50,
            'call_margin': 0.02, 'raise_eq': 0.72, 'icm_w': 1.0, 'soft': 0.25, 'mc_ns': 85000,
            'bluff': 1.0, 'def_bb': 1.0, 'threebet': 1.0, 'press': 0.0, 'icm_m': 0.002, 'callp': 1.0,
        }
        if params:
            self.P.update(params)
            if 'seed' in params:
                self.rng = random.Random(params['seed'])
        self.new_table({}, 0, 8)

    # -------------------------------------------------------- interface
    def new_table(self, rules, seat, n_players):
        try:
            self.seat = seat
            self.n = n_players or 8
            self.opps = [Opp() for _ in range(max(self.n, 10))]
            self.hand = -1
            self.rp = None
            self.pfa = False
            self.rules = rules or {}
            self.start_stack = (rules or {}).get('starting_stack', 2000) if isinstance(rules, dict) else 2000
            self.cap = int((rules or {}).get('hand_cap', 200)) if isinstance(rules, dict) else 200
            if self.cap < 20: self.cap = 200
        except Exception:
            self.opps = [Opp() for _ in range(10)]
            self.hand = -1; self.rp = None; self.n = 8; self.cap = 200

    def hand_end(self, result):
        try:
            if isinstance(result, dict) and self.rp is not None:
                h = result.get('history')
                if h:
                    self.rp.feed(h, self.opps, self.seat)
        except Exception:
            pass
        self.rp = None

    def act(self, obs):
        t0 = _pc()
        try:
            a = self._act(obs, t0)
        except Exception:
            try:
                a = self._fallback(obs)
            except Exception:
                a = None
        return self._legalize(obs, a)

    def _fallback(self, o):
        """minimal-field strategy used only if the main path raises (unexpected obs shapes)."""
        h = list(o.hole)
        b = list(o.board or ())
        legal = o.legal
        tc = o.to_call or 0
        if not b:
            pc = PCT[CLS[h[0] * 52 + h[1]]]
            if pc <= 0.06 and 'raise' in legal:
                return ('raise', o.max_raise)
            if pc <= 0.20 and tc <= 0.1 * max(1, o.max_raise):
                return ('call', 0) if 'call' in legal else ('check', 0)
            return ('check', 0) if 'check' in legal else ('fold', 0)
        v = ev(h + b) >> 20
        if v >= 2 and 'raise' in legal and tc == 0:
            return ('raise', o.min_raise)
        if v >= 1 and tc <= 0.5 * max(1, (o.pot or 0) + sum(o.bets or [0])):
            return ('call', 0) if 'call' in legal else ('check', 0)
        return ('check', 0) if 'check' in legal else ('fold', 0)

    def _legalize(self, o, a):
        try:
            legal = o.legal
            if a is not None and isinstance(a, tuple) and len(a) == 2:
                k = a[0]
                if k == 'raise':
                    if 'raise' in legal:
                        x = int(a[1])
                        if x < o.min_raise: x = o.min_raise
                        if x > o.max_raise: x = o.max_raise
                        return ('raise', int(x))
                    k = 'call'
                if k == 'call' and 'call' not in legal:
                    k = 'check'
                if k == 'check' and 'check' not in legal:
                    k = 'fold'
                if k == 'fold' and 'check' in legal:
                    k = 'check'
                if k in legal:
                    return (k, 0)
            if 'check' in legal:
                return ('check', 0)
            return ('fold', 0) if 'fold' in legal else (next(iter(legal)), 0)
        except Exception:
            return ('fold', 0)

    # -------------------------------------------------------- helpers
    def _sync(self, o):
        n = len(o.stacks)
        if len(self.opps) < n:
            self.opps.extend(Opp() for _ in range(n - len(self.opps)))
        if o.hand_no != self.hand or self.rp is None:
            # new hand
            self.hand = o.hand_no
            self.pfa = False
            self.rp = None
            if o.street == 0 and not o.pot:
                start = [o.stacks[i] + o.bets[i] for i in range(n)]
                try:
                    self.rp = Replay(n, start, o.button, o.blinds[0], o.blinds[1])
                except Exception:
                    self.rp = None
        if self.rp is not None:
            try:
                self.rp.feed(o.history or [], self.opps, o.seat)
                if self.rp.street != o.street:
                    self.rp.ok = False
            except Exception:
                self.rp = None

    def _act(self, o, t0):
        self._sync(o)
        if o.street == 0:
            return self._preflop(o, t0)
        return self._postflop(o, t0)

    def _alive_stacks(self, o):
        """total chips per seat this hand (behind + this street's bet)."""
        return [o.stacks[i] + o.bets[i] for i in range(len(o.stacks))]

    def _icm(self, o, mine, other_change=None):
        """our ICM equity with final stack `mine`. Others start at stack+bet (chips they own this hand);
        other_change: dict seat->final stack for players whose outcome differs."""
        n = len(o.stacks)
        me = o.seat
        others = []
        nplayers = 1
        for i in range(n):
            if i == me: continue
            v = o.stacks[i] + o.bets[i]
            if v <= 0 and not o.in_hand[i]:
                continue
            nplayers += 1
            if other_change and i in other_change:
                v = other_change[i]
            if v > 0:
                others.append(v)
        pts = POINTS[:nplayers] if nplayers <= 8 else POINTS + [0] * (nplayers - 8)
        if mine <= 0:
            return pts[nplayers - 1]
        return icm_me(mine, others, pts[:len(others) + 1])

    def _dead(self, o, keep):
        """final stacks for players (not in keep, not me) who lose their bets this hand."""
        d = {}
        for i in range(len(o.stacks)):
            if i != o.seat and i not in keep and o.bets[i] > 0:
                d[i] = o.stacks[i]
        return d

    def _util(self, o, mine, other_change=None):
        """ICM blended with a floor-plus-linear chip model; the chip share grows with blind pressure
        (chips we would bleed folding to the hand cap), since pure ICM overvalues folding."""
        e = self._icm(o, mine, other_change)
        w = self.P['icm_w']
        n = len(o.stacks)
        nal = 0; tot = o.pot
        for i in range(n):
            v = o.stacks[i] + o.bets[i]
            tot += v
            if v > 0 or o.in_hand[i]: nal += 1
        if nal < 2:
            return e
        cap = self.cap
        hn = o.hand_no if isinstance(o.hand_no, int) else cap // 2
        H = max(0, cap - hn)
        cost = H / float(nal) * (o.blinds[0] + o.blinds[1])
        mys = max(1, o.stacks[o.seat] + o.bets[o.seat])
        pressure = min(1.0, cost / mys)
        w = w * (1.0 - self.P['press'] * pressure)
        if w >= 0.999:
            return e
        pts = POINTS[:nal] if nal <= 8 else POINTS + [0] * (nal - 8)
        floor = pts[nal - 1]
        chip = floor + (sum(pts) - nal * floor) * max(0, mine) / float(max(1, tot))
        return w * e + (1 - w) * chip

    # -------------------------------------------------------- preflop
    def _pf_order(self, o):
        n = len(o.stacks)
        alive = [s for s in range(n) if o.stacks[s] > 0 or o.bets[s] > 0 or o.in_hand[s]]
        order = []
        s = (o.button + 1) % n
        for _ in range(n):
            if s in alive: order.append(s)
            s = (s + 1) % n
        if len(order) == 2:
            b = o.button if o.button in order else order[1]
            other = order[0] if order[0] != b else order[1]
            return [b, other], b, other
        if len(order) < 2:
            return order, -1, -1
        return order[2:] + order[:2], order[0], order[1]

    def _range_of_raiser(self, op, o, seat, raise_to, bb, behind_at_raise):
        """top-x estimate for a preflop raiser."""
        w = op.wild()
        st = o.stacks[seat] + o.bets[seat]
        allin = o.stacks[seat] == 0
        if allin:
            # shove range: widen for short stacks, use observed shove frequency
            sbb = st / float(bb)
            base = 0.10 if sbb > 25 else (0.16 if sbb > 15 else (0.25 if sbb > 8 else 0.40))
            sr = op.shove_rate()
            if op.shoves >= 2:
                x = max(min(base, 0.5), min(1.0, sr * 1.4))
            else:
                x = base
        else:
            x = op.open_rate() * (1.25 if behind_at_raise <= 2 else 0.9)
            size = raise_to / float(bb)
            if size > 4.5 and op.un_raise < 3:
                x *= 0.8
        x = x + (1.0 - x) * w * 0.9
        return max(0.02, min(1.0, x))

    def _preflop(self, o, t0):
        P = self.P
        n = len(o.stacks); me = o.seat
        sb, bb = o.blinds
        bb = max(1, bb)
        c = CLS[o.hole[0] * 52 + o.hole[1]]
        pc = PCT[c]
        rp = self.rp
        mx = max(o.bets)
        mytot = o.stacks[me] + o.bets[me]
        opps = [i for i in range(n) if o.in_hand[i] and i != me]
        if not opps:
            return ('check', 0)
        tots = self._alive_stacks(o)
        eff = min(mytot, max(tots[i] for i in opps))
        eff_bb = eff / float(bb)
        pf_order, sbs, bbs = self._pf_order(o)
        # behind: players after us in preflop order still to act (unopened case)
        if me in pf_order:
            pos = pf_order.index(me)
            behind = [s for s in pf_order[pos + 1:] if o.in_hand[s] and (o.stacks[s] > 0)]
        else:
            behind = [s for s in opps]
        nraises = rp.pf_raises if (rp is not None and rp.ok) else (0 if mx <= bb else (1 if mx <= 4 * bb else 2))
        raiser = rp.pf_raiser if (rp is not None and rp.ok and rp.pf_raiser >= 0) else -1
        if raiser < 0 and mx > bb:
            raiser = max(opps, key=lambda i: o.bets[i])
        pot = o.pot + sum(o.bets)
        to_call = o.to_call
        # ---------------- unopened (maybe limpers)
        if mx <= bb or nraises == 0:
            limpers = [i for i in opps if o.bets[i] >= bb and i != bbs]
            if eff_bb <= P['push_bb'] + (2 if not limpers else 0) or (mytot / float(bb)) <= P['push_bb']:
                return self._shove_or_fold(o, c, behind, limpers, pot, bb)
            nb = len(behind)
            base = {0: 0.0, 1: 0.45, 2: 0.38, 3: 0.27, 4: 0.21, 5: 0.17, 6: 0.15, 7: 0.13}.get(nb, 0.12)
            nal = sum(1 for i in range(n) if o.stacks[i] + o.bets[i] > 0)
            if me == sbs and nb == 1:
                base = 0.40
            if nal == 2:
                base = 0.70
            elif nal == 3 and nb == 2:
                base = 0.45
            # adapt to players behind: if they fold a lot, open wider; if they 3-bet a lot, tighten
            if behind:
                ftr = sum(self.opps[s].fold_to_raise() for s in behind) / len(behind)
                tb = max(self.opps[s].threebet_rate() + self.opps[s].wild() * 0.3 for s in behind)
                adj = 1.0 + (ftr - 0.75) * 1.2 - max(0.0, tb - 0.08) * 2.0
                base *= max(0.6, min(1.5, adj))
            base *= P['open_mult']
            if limpers:
                # isolate: tighter vs passive limpers, value-heavy
                lw = max(self.opps[s].wild() for s in limpers)
                base = base * 0.55 + 0.10 * lw
            if to_call == 0:
                # big blind option (or everyone limped to us)
                if pc <= min(base, 0.12) + 0.05 * len(limpers) * 0:
                    return ('raise', int(mx + (3 + len(limpers)) * bb))
                return ('check', 0)
            if pc <= base:
                size = 2.5 if eff_bb >= 30 else 2.2
                if o.hand_no <= 25 and eff_bb > 60:
                    size = 2.5
                to = int(bb * (size + 1.0 * len(limpers) + (0.5 if me == sbs else 0)))
                if to >= 0.45 * mytot:
                    to = o.max_raise
                return ('raise', to)
            # complete small blind / overlimp with cheap speculative hands when deep
            if limpers and eff_bb > 40 and to_call <= bb and (pc <= 0.30 or (me == sbs and pc <= 0.5)):
                return ('call', 0)
            if me == sbs and nb == 1 and to_call <= bb / 2 + 1 and pc <= 0.55 and eff_bb > 25:
                return ('call', 0)
            return ('fold', 0)
        # ---------------- facing raise(s)
        op = self.opps[raiser]
        rto = o.bets[raiser]
        rp_behind = 3
        x = self._range_of_raiser(op, o, raiser, rto, bb, rp_behind)
        if nraises >= 2:
            x3 = self.opps[raiser].threebet_rate() * 1.0 + self.opps[raiser].wild() * 0.5
            x = max(0.02, min(1.0, min(x, x3) if o.stacks[raiser] > 0 else x))
        # callers in between -> stronger field; multiway penalty
        others_in = [i for i in opps if i != raiser and o.bets[i] > 0 and o.bets[i] >= rto * 0.99]
        e = eq_top(c, x)
        if others_in:
            for i in others_in:
                e *= eq_top(c, min(1.0, max(0.03, x * 1.6))) * 1.15
            e = min(e, 0.95)
        call_cost = min(to_call, o.stacks[me])
        commit_frac = (o.bets[me] + call_cost) / float(max(1, mytot))
        # all-in or committing call -> ICM decision
        if o.stacks[raiser] == 0 or commit_frac > 0.45 or rto >= 0.45 * mytot:
            return self._call_allin_pf(o, c, e, raiser, others_in, behind)
        # short: reshove or fold
        if eff_bb <= P['push_bb'] + 4:
            return self._reshove_decision(o, c, e, raiser, others_in, behind, x)
        # deep stack: 3-bet / call / fold
        rnd = self.rng.random()
        in_pos = me == o.button or (len(behind) == 0 and me != sbs and me != bbs)
        if nraises == 1:
            val_x = max(0.025, min(0.07, x * 0.25)) * P['threebet']
            if pc <= val_x or (e > 0.60 and pc <= 0.10):
                to = int(rto * (3.0 if in_pos else 3.6) + call_cost * 0 + sum(o.bets[i] for i in others_in))
                if to >= 0.4 * mytot:
                    to = o.max_raise
                return ('raise', to)
            # light 3-bet vs wide, foldy openers (suited wheel aces, suited broadways)
            if not others_in and x >= 0.25 and op.f3_fold + 1 > op.f3_cont and pc <= 0.30 and rnd < 0.25 * P['bluff']:
                if (c // 13 == 12 or c % 13 == 12) or pc <= 0.12:
                    to = int(rto * (3.0 if in_pos else 3.6))
                    if to < 0.4 * mytot:
                        return ('raise', to)
            # call
            potodds = call_cost / float(pot + call_cost)
            need = potodds + 0.06 - (0.05 if in_pos else 0.0) + (0.02 if others_in else 0.0)
            if me == bbs:
                need -= 0.04 * P['def_bb']
            pair = c % 14 == 0
            suited_conn = (c // 13 > c % 13) and abs(c // 13 - c % 13) <= 2
            implied = eff_bb > 40 and call_cost <= 0.06 * eff and (pair or suited_conn)
            if e >= max(need, 0.33) or (implied and e >= 0.30) or (me == bbs and e >= need and call_cost <= 2.5 * bb):
                if call_cost <= 0.2 * mytot:
                    return ('call', 0)
            return ('fold', 0)
        # facing a 3-bet or more (not all-in yet)
        if pc <= max(0.02, min(0.10, x * 0.45)) or e > 0.60:
            return ('raise', o.max_raise)
        potodds = call_cost / float(pot + call_cost)
        if e >= potodds + 0.08 and call_cost <= 0.25 * mytot and pc <= max(0.08, min(0.16, x * 0.8)):
            return ('call', 0)
        return ('fold', 0)

    def _callers_model(self, s, shove_bb, bb_seat):
        """(probability of calling a shove, range width of calls) for seat s."""
        op = self.opps[s]
        w = op.wild()
        base = 0.09 + max(0.0, (12.0 - shove_bb)) * 0.012
        if s == bb_seat:
            base += 0.05
        cv = op.call_vs_raise()
        base = base * (0.6 + 1.6 * cv) * self.P['callp']
        p = min(0.95, base + (0.45 - base) * w)
        xr = min(1.0, p + (1.0 - p) * w)
        return p, xr

    def _shove_or_fold(self, o, c, behind, limpers, pot, bb):
        me = o.seat
        mytot = o.stacks[me] + o.bets[me]
        S = o.stacks[me]
        u_fold = self._util(o, S)
        pf_order, sbs, bbs = self._pf_order(o)
        callers = [s for s in behind] + [s for s in limpers if s not in behind]
        if not callers:
            return ('check', 0) if 'check' in o.legal else ('call', 0)
        pfold = 1.0
        ev = 0.0
        rem = 1.0
        D_all = pot
        for s in callers:
            ts = o.stacks[s] + o.bets[s]
            E = min(mytot, ts)
            shove_bb = E / float(bb)
            p, xr = self._callers_model(s, shove_bb, bbs)
            if s in limpers:
                p = min(0.9, p * 1.3)
            eq = eq_top(c, xr)
            D = pot - o.bets[me] - o.bets[s]
            win_f = mytot + E + D
            lose_f = mytot - E
            dd = self._dead(o, (s,))
            dw = dict(dd); dw[s] = ts - E
            dl = dict(dd); dl[s] = ts + E + D
            u_w = self._util(o, win_f, dw)
            u_l = self._util(o, lose_f, dl)
            ev += rem * p * (eq * u_w + (1 - eq) * u_l)
            rem *= (1 - p)
        ev += rem * self._util(o, S + pot, self._dead(o, ()))
        if ev > u_fold + self.P['icm_m']:
            return ('raise', o.max_raise)
        if 'check' in o.legal:
            return ('check', 0)
        return ('fold', 0)

    def _call_allin_pf(self, o, c, e, raiser, others_in, behind):
        me = o.seat
        mytot = o.stacks[me] + o.bets[me]
        S = o.stacks[me]
        pot = o.pot + sum(o.bets)
        rt = o.stacks[raiser] + o.bets[raiser]
        call_amt = min(o.to_call, S)
        dd = self._dead(o, (raiser,))
        fo = dict(dd); fo[raiser] = o.stacks[raiser] + pot - o.bets[me]
        u_fold = self._util(o, S, fo)
        # assume everyone else folds; amount at risk = what we can match
        E = min(mytot, rt)
        D = pot - o.bets[me] - o.bets[raiser]
        win_f = mytot + E + D
        lose_f = mytot - E
        dw = dict(dd); dw[raiser] = rt - E
        dl = dict(dd); dl[raiser] = rt + E + D
        u_w = self._util(o, win_f, dw)
        u_l = self._util(o, lose_f, dl)
        u_call = e * u_w + (1 - e) * u_l
        if u_call > u_fold + self.P['icm_m']:
            if 'raise' in o.legal and o.stacks[raiser] > 0 and e > 0.55:
                return ('raise', o.max_raise)
            return ('call', 0)
        return ('fold', 0)

    def _reshove_decision(self, o, c, e, raiser, others_in, behind, x):
        """we are short-ish facing a non-all-in raise: shove or fold (call only if almost committed)."""
        me = o.seat
        mytot = o.stacks[me] + o.bets[me]
        S = o.stacks[me]
        pot = o.pot + sum(o.bets)
        op = self.opps[raiser]
        rt = o.stacks[raiser] + o.bets[raiser]
        dd = self._dead(o, (raiser,))
        fo = dict(dd); fo[raiser] = o.stacks[raiser] + pot - o.bets[me]
        u_fold = self._util(o, S, fo)
        E = min(mytot, rt)
        # raiser calls our shove with top portion of his range
        pr = min(1.0, 0.45 + 0.5 * op.wild() + (0.2 if E <= 2.2 * o.bets[raiser] else 0.0))
        xr = max(0.02, x * pr)
        eq = eq_top(c, xr)
        D = pot - o.bets[me] - o.bets[raiser]
        dw = dict(dd); dw[raiser] = rt - E
        dl = dict(dd); dl[raiser] = rt + E + D
        u_w = self._util(o, mytot + E + D, dw)
        u_l = self._util(o, mytot - E, dl)
        u_steal = self._util(o, S + pot, self._dead(o, ()))
        rem = 1.0
        evv = 0.0
        pf_order, sbs, bbs = self._pf_order(o)
        for s in behind + others_in:
            if s == raiser: continue
            ts = o.stacks[s] + o.bets[s]
            p, xs = self._callers_model(s, min(mytot, ts) / float(o.blinds[1]), bbs)
            p *= 0.7
            eqs = eq_top(c, xs)
            Es = min(mytot, ts)
            d2 = self._dead(o, (s,))
            dw2 = dict(d2); dw2[s] = ts - Es
            dl2 = dict(d2); dl2[s] = ts + Es + pot - o.bets[me] - o.bets[s]
            evv += rem * p * (eqs * self._util(o, mytot + Es + pot - o.bets[me] - o.bets[s], dw2) +
                              (1 - eqs) * self._util(o, mytot - Es, dl2))
            rem *= (1 - p)
        evv += rem * (pr * (eq * u_w + (1 - eq) * u_l) + (1 - pr) * u_steal)
        if evv > u_fold + self.P['icm_m']:
            return ('raise', o.max_raise)
        return ('fold', 0)

    # -------------------------------------------------------- postflop
    def _postflop(self, o, t0):
        P = self.P
        n = len(o.stacks); me = o.seat
        bb = max(1, o.blinds[1])
        opps = [i for i in range(n) if o.in_hand[i] and i != me]
        if not opps:
            return ('check', 0)
        rp = self.rp
        ok = rp is not None and rp.ok
        pot = o.pot + sum(o.bets)
        to_call = o.to_call
        S = o.stacks[me]
        mx = max(o.bets)
        # ranges per opponent (preflop width), narrowing for the aggressor
        ranges = []
        pfr = rp.pf_raiser if ok else -1
        we_pfa = pfr == me
        aggr = -1
        if to_call > 0:
            aggr = rp.aggr if (ok and rp.aggr >= 0 and rp.aggr != me) else max(opps, key=lambda i: o.bets[i])
        los = []
        for i in opps:
            op = self.opps[i]
            w = op.wild()
            pa = rp.pf_act[i] if ok else ''
            lo = 0.0
            if i == pfr:
                x = op.open_rate() * 1.1
                if ok and rp.pf_raises >= 2:
                    x = min(x, op.threebet_rate() * 1.3 + 0.02)
            else:
                x = min(0.6, op.vpip_rate() * 1.1)
                if pfr >= 0 and pfr != i:
                    x = min(x, 0.45)
                    if pa == 'call':
                        lo = 0.025      # flatted a raise: premiums would usually have re-raised
                elif pa in ('call', 'check'):
                    lo = 0.05           # limped / checked option: capped range
                    if pa == 'check':
                        x = 1.0
            x = x + (1 - x) * w
            lo = lo * (1 - w)
            x = max(0.04, min(1.0, x))
            ranges.append(x)
            los.append(min(lo, x * 0.5))
        q = 1.0
        nidx = -1
        if aggr >= 0 and aggr in opps:
            nidx = opps.index(aggr)
            op = self.opps[aggr]
            br = op.bet_rate() if o.bets[me] == 0 else op.raise_vs_bet() * 2.0
            if o.bets[me] > 0:
                br = min(br, 0.45)
            # bigger bets are stronger (for non-wild)
            frac = (o.bets[aggr] - o.bets[me]) / float(max(1, pot - (o.bets[aggr] - o.bets[me])))
            q = br * (1.15 - 0.25 * min(2.0, frac))
            # repeated aggression this hand narrows further
            if ok:
                cnt = sum(rp.aggr_cnt[aggr][1:])
                q *= 0.85 ** max(0, cnt - 1)
            w = op.wild()
            q = q + (1 - q) * w * 0.9
            q = max(0.12, min(1.0, q))
        deadline = t0 + P['mc_ns']
        res = self._mc(o.hole, o.board, ranges, nidx, q, deadline, los)
        if res is None:
            return ('check', 0) if 'check' in o.legal else ('fold', 0)
        e_all, e_n, e_top = res
        nopp = len(opps)
        street = o.street
        rnd = self.rng.random()
        eff = min(S + o.bets[me], max(o.stacks[i] + o.bets[i] for i in opps))
        spr = eff / float(max(1, pot))
        if to_call == 0:
            # value bet?
            thr = P['vbet_hu'] if nopp == 1 else P['vbet_mw'] - 0.04 * (nopp - 2)
            ftb0 = sum(self.opps[i].fold_to_bet() for i in opps) / nopp
            # vs stations their calling range is their whole range
            ev_c = e_all + 0.06 if ftb0 < 0.3 else e_top
            if ev_c > thr - 0.08 and e_all > 0.5 + (0.0 if nopp == 1 else -0.12 * (nopp - 1)):
                frac = (0.55 if e_top < 0.8 else 0.7) if street == 1 else (0.66 if e_top < 0.8 else 0.8)
                if street == 3 and e_top > 0.85:
                    frac = 1.0
                # vs stations: bigger value bets
                if ftb0 < 0.3:
                    frac *= 1.25
                frac *= 0.9 + 0.2 * rnd
                amt = int(pot * frac)
                if amt >= 0.6 * S or spr < 1.3:
                    return ('raise', o.max_raise)
                return ('raise', max(o.min_raise, amt))
            # c-bet / bluff
            ftb = sum(self.opps[i].fold_to_bet() for i in opps) / nopp
            checked_to = ok and len(o.history or ()) > 0 and all(
                a[1][0] == 'check' for a in self._street_actions(o) if a[0] != me) and len(self._street_actions(o)) > 0
            drawy = street < 3 and self._draw(o.hole, o.board)
            if nopp <= 2 and street <= 2:
                cb = P['cbet'] * (ftb / 0.45) * P['bluff']
                if nopp == 2: cb *= 0.5
                if street == 2: cb *= 0.45 * (1.0 if we_pfa else 0.7)
                if not we_pfa and street == 1: cb *= 0.5
                if checked_to: cb *= 1.3
                if drawy: cb = cb * 1.4 + 0.15
                if (e_all > 0.30 or drawy) and rnd < min(0.85, cb):
                    return ('raise', max(o.min_raise, int(pot * (0.5 if street == 1 else 0.62) * (0.9 + 0.2 * self.rng.random()))))
            if nopp == 1 and street == 3 and e_all < 0.15 and ftb > 0.55 and rnd < 0.25 * P['bluff']:
                return ('raise', max(o.min_raise, int(pot * 0.7)))
            return ('check', 0)
        # facing a bet
        call_amt = min(to_call, S)
        potodds = call_amt / float(pot + call_amt)
        e = e_n
        # risk adjustment: large fraction of our stack -> ICM
        if call_amt >= 0.35 * S + 1 or call_amt >= S:
            # approximate showdown: all-in-ish decision vs aggressor
            agg = aggr if aggr >= 0 else opps[0]
            at = o.stacks[agg] + o.bets[agg]
            mytot = S + o.bets[me]
            E = min(mytot, at)
            D = pot - o.bets[me] - o.bets[agg]
            dd = self._dead(o, (agg,))
            fo = dict(dd); fo[agg] = o.stacks[agg] + pot - o.bets[me]
            u_fold = self._util(o, S, fo)
            dw = dict(dd); dw[agg] = at - E
            dl = dict(dd); dl[agg] = at + E + D
            u_w = self._util(o, mytot + E + D, dw)
            u_l = self._util(o, mytot - E, dl)
            # equity when committed: blend toward showdown equity
            u_call = e * u_w + (1 - e) * u_l
            if u_call > u_fold + self.P['icm_m']:
                if e > P['raise_eq'] and 'raise' in o.legal and o.stacks[agg] > 0:
                    return ('raise', o.max_raise)
                return ('call', 0)
            return ('fold', 0)
        # value raise
        if e > P['raise_eq'] + 0.04 * (nopp - 1) and 'raise' in o.legal:
            to = int(mx * 2.6 + (pot - sum(o.bets)) * 0.4 + sum(o.bets) * 0.3)
            if to >= 0.5 * (S + o.bets[me]) or spr < 2:
                return ('raise', o.max_raise)
            return ('raise', to)
        callers = sum(1 for i in opps if i != aggr and o.bets[i] >= mx and mx > 0)
        margin = P['call_margin'] + (0.03 if street < 3 and nopp == 1 else 0.0) + 0.02 * (nopp - 1) + 0.04 * callers
        if e >= potodds + margin:
            return ('call', 0)
        # semi-bluff raise with a strong draw, heads-up, when cheap relative to stack
        if street == 1 and nopp == 1 and 'raise' in o.legal and e >= potodds - 0.04 and \
                self._draw(o.hole, o.board) and rnd < 0.35 * P['bluff'] and call_amt < 0.15 * S:
            agg = aggr if aggr >= 0 else opps[0]
            if self.opps[agg].raise_vs_bet() < 0.25:
                return ('raise', int(mx * 2.8 + (pot - sum(o.bets)) * 0.3))
        if e >= potodds - 0.02 and street < 3 and self._draw(o.hole, o.board) and call_amt < 0.1 * S:
            return ('call', 0)
        return ('fold', 0)

    def _street_actions(self, o):
        """actions on the current street (from the replay index of street start)."""
        rp = self.rp
        if rp is None or not rp.ok:
            return []
        return rp.cur_actions

    @staticmethod
    def _draw(hole, board):
        """True for a flush draw or open-ended straight draw that uses a hole card."""
        cards = list(hole) + list(board)
        sc = [0, 0, 0, 0]
        for c in cards: sc[c & 3] += 1
        for su in range(4):
            if sc[su] == 4 and ((hole[0] & 3) == su or (hole[1] & 3) == su):
                return True
        m = 0
        for c in cards: m |= 1 << (c >> 2)
        hm = (1 << (hole[0] >> 2)) | (1 << (hole[1] >> 2))
        mm = (m << 1) | ((m >> 12) & 1)
        hmm = (hm << 1) | ((hm >> 12) & 1)
        for lo in range(1, 11):
            w = (mm >> lo) & 0xF
            if w == 0xF and (hmm >> lo) & 0xF and STR[m] < 0:
                # 4 consecutive ranks, open on both ends (not A-high/wheel blocked)
                if lo >= 1 and lo + 4 <= 13:
                    return True
        return False

    def _mc(self, hole, board, ranges, nidx, q, deadline, los=None):
        """returns (eq vs ranges, eq vs narrowed aggressor, eq vs top-half by current strength)."""
        rnd = self.rng.random
        dead = 0
        for c in hole: dead |= 1 << c
        for c in board: dead |= 1 << c
        kb = 0
        for c in board: kb += CK[c]
        need = 5 - len(board)
        h0, h1 = hole
        kh = kb + CK[h0] + CK[h1]
        bsm = [0, 0, 0, 0]
        for c in board: bsm[c & 3] |= RB[c]
        hsm = bsm[:]
        hsm[h0 & 3] |= RB[h0]; hsm[h1 & 3] |= RB[h1]
        nopp = len(ranges)
        tops = [max(20, min(1326, int(x * 1326))) for x in ranges]
        lows = [int(l * 1326) for l in los] if los else [0] * len(tops)
        spans = [max(10, tops[i] - lows[i]) for i in range(len(tops))]
        outs = []   # (cur_strength_of_narrow_opp, max_cur_all, result)
        NFg = NF.get; FSl = FS; FLl = FL; CKl = CK; RBl = RB; ALA = ALLA; ALB = ALLB
        it = 0
        cap = 300
        minit = 24 if nopp <= 2 else 12
        while it < cap:
            if (nopp > 2 or it & 3 == 0) and it >= minit and _pc() > deadline:
                if it >= 48 or _pc() > deadline + 350000:
                    break
            it += 1
            dm = dead
            oc = []
            for oi in range(nopp):
                lw = lows[oi]; sp = spans[oi]
                for _ in range(12):
                    j = lw + int(rnd() * sp)
                    if j > 1325: j = 1325
                    a = ALA[j]; b = ALB[j]
                    if not ((dm >> a) & 1 or (dm >> b) & 1):
                        break
                else:
                    # fallback: any free combo
                    while True:
                        a = int(rnd() * 52); b = int(rnd() * 52)
                        if a != b and not ((dm >> a) & 1 or (dm >> b) & 1):
                            break
                dm |= (1 << a) | (1 << b)
                oc.append((a, b))
            kr = 0
            rc = []
            while len(rc) < need:
                x = int(rnd() * 52)
                if not (dm >> x) & 1:
                    dm |= 1 << x; rc.append(x); kr += CKl[x]
            k = kh + kr
            fs = FSl[k >> 31]
            if fs < 0:
                mv = NFg(k & M31)
            else:
                m = hsm[fs]
                for x in rc:
                    if x & 3 == fs: m |= RBl[x]
                mv = FLl[m]
            best = -1; ties = 0; curn = 0; curmax = 0
            for i in range(nopp):
                a, b = oc[i]
                k = kb + kr + CKl[a] + CKl[b]
                fs = FSl[k >> 31]
                if fs < 0:
                    v = NFg(k & M31)
                else:
                    m = bsm[fs]
                    if a & 3 == fs: m |= RBl[a]
                    if b & 3 == fs: m |= RBl[b]
                    for x in rc:
                        if x & 3 == fs: m |= RBl[x]
                    v = FLl[m]
                if v > best:
                    best = v; ties = 1
                elif v == best:
                    ties += 1
                if need:
                    kc = kb + CKl[a] + CKl[b]
                    fs = FSl[kc >> 31]
                    if fs < 0:
                        cv = NFg(kc & M31)
                    else:
                        m = bsm[fs]
                        if a & 3 == fs: m |= RBl[a]
                        if b & 3 == fs: m |= RBl[b]
                        cv = FLl[m]
                else:
                    cv = v
                # crude draw credit so semi-bluffs rank above air
                if i == nidx:
                    curn = cv
                if cv > curmax:
                    curmax = cv
            if mv > best:
                r = 1.0
            elif mv == best:
                r = 1.0 / (ties + 1)
            else:
                r = 0.0
            outs.append((curn, curmax, r))
        N = len(outs)
        if N < 8:
            return None
        e_all = sum(x[2] for x in outs) / N
        soft = self.P['soft']
        if nidx >= 0 and q < 0.999:
            cs = sorted([x[0] for x in outs], reverse=True)
            kq = max(1, int(q * N + 0.5))
            thr = cs[kq - 1]
            sw = 0.0; sr = 0.0
            for x in outs:
                w = 1.0 if x[0] >= thr else soft
                sw += w; sr += w * x[2]
            e_n = sr / sw
        else:
            e_n = e_all
        cs = sorted([x[1] for x in outs], reverse=True)
        thr = cs[N // 2]
        sw = 0; sr = 0.0
        for x in outs:
            if x[1] >= thr:
                sw += 1; sr += x[2]
        e_top = sr / sw if sw else e_all
        return e_all, e_n, e_top


